package com.nextfeet.nextfeet.service; import java.util.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Pedido; import com.nextfeet.nextfeet.repository.PedidoDAO; @Service public class PedidoServiceImpl implements PedidoService {private final PedidoDAO dao; public PedidoServiceImpl(PedidoDAO dao){this.dao=dao;} public List<Pedido> listarPorUsuario(Integer id){return dao.listarPorUsuario(id);} public List<Pedido> listarTodos(){return dao.listarTodos();} public Pedido obtener(Integer id){return dao.obtener(id);} public Integer crear(Pedido p){return dao.crear(p);} public void actualizarEstado(Integer id,String e){dao.actualizarEstado(id,e);} public void anular(Integer id,String m){dao.anular(id,m);}}